extern "C" void studio_roots_geometry(bool);
extern "C" int preflight_scene_audio_probe(obs_scene_t *);
static bool armed=false;static int enumChecks=0,locked=0;static std::vector<obs_scene_t*> probes;
void preflightEnum(void *v,obs_source_enum_proc_t cb,void *p){if(armed){std::thread worker([]{for(auto *s:probes){++enumChecks;if(preflight_scene_audio_probe(s))++locked;}});worker.join();}enumerate(v,cb,p);}
void verify(const char *label){check(enumChecks>0&&locked==0,label);enumChecks=locked=0;}
int main(int argc,char **argv){if(argc!=2||std::filesystem::exists(argv[1]))return 2;checks=obs_data_array_create();check(obs_startup("en-US",nullptr,nullptr),"Native preflight-lock core startup");obs_source_info i{};i.id="graph_probe";i.type=OBS_SOURCE_TYPE_INPUT;i.output_flags=0;i.get_name=name;i.create=create;i.destroy=destroy;i.enum_active_sources=preflightEnum;i.enum_all_sources=preflightEnum;obs_register_source(&i);studio_roots_geometry(true);auto *scene=obs_scene_create_private("preflight parent");auto *leaf=source("preflight leaf");auto *item=obs_scene_add(scene,leaf);auto *group=obs_scene_add_group(scene,"preflight group");auto *gs=obs_sceneitem_group_get_scene(group);probes={scene,gs};armed=true;obs_sceneitem_group_add_item(group,item);verify("group_add_item generic enum runs before either own scene audio lock");obs_sceneitem_group_remove_item(group,item);verify("group_remove_item generic enum runs before either own scene audio lock");obs_sceneitem_t *members[]={item};auto *inserted=obs_scene_insert_group(scene,"preflight inserted",members,1);verify("insert_group generic enum runs before own scene audio locks");obs_sceneitem_order_info out[]={{nullptr,group},{nullptr,inserted},{nullptr,item}};check(obs_scene_reorder_items2(scene,out,3),"Native reorder moves child out");verify("reorder_items2 generic enum runs before parent audio lock");obs_sceneitem_order_info into[]={{nullptr,group},{group,item},{nullptr,inserted}};check(obs_scene_reorder_items2(scene,into,3),"Native reorder moves child in");verify("reorder_items2 into group generic enum runs before parent audio lock");armed=false;probes.clear();obs_scene_release(scene);obs_source_release(leaf);studio_graph_drain();studio_roots_geometry(false);obs_shutdown();auto *r=obs_data_create();obs_data_set_array(r,"checks",checks);obs_data_set_int(r,"failures",failures);obs_data_set_bool(r,"passed",!failures);obs_data_set_string(r,"scope","Actual structural APIs invoke adversarial source enumeration; a separate worker trylocks scene audio mutexes during each callback. This proves this caller holds none of those audio locks at new preflight call sites; not arbitrary outer caller locks or full UI/thread-safety.");obs_data_save_json_safe(r,argv[1],"tmp",nullptr);obs_data_release(r);obs_data_array_release(checks);return failures?1:0;}
